     2→import type { BridgeStatus, DeviceInfo, PlayerInfo, BridgeState } from "../types";
     3→
     4→export type DotStatus = "connected" | "disconnected" | "degraded";
     5→
     6→/** Statuses considered "non-running" for recovery detection. */
     7→const NON_RUNNING_STATUSES: ReadonlySet<BridgeStatus> = new Set([
     8→  "stopped",
     9→  "starting",
    10→  "crashed",
    11→  "no_jre",
    12→  "no_jar",
    13→  "fallback",
    14→  "waiting_for_hardware",
    15→  "not_initialized",
    16→]);
    17→
    18→interface BridgeStoreState {
    19→  // WebSocket connection state
    20→  wsConnected: boolean;
    21→
    22→  // Bridge state (from WebSocket bridge_status messages)
    23→  status: BridgeStatus;
    24→  port: number;
    25→  networkInterface: string | null;
    26→  jarExists: boolean;
    27→  jreAvailable: boolean;
    28→  restartCount: number;
    29→  restartAttempt: number;
    30→  nextRetryInS: number | null;
    31→  routeCorrect: boolean | null;
    32→  routeWarning: string | null;
    33→  devices: Record<string, DeviceInfo>;
    34→  players: Record<string, PlayerInfo>;
    35→
    36→  // Pioneer liveness (from WebSocket pioneer_status messages)
    37→  isReceiving: boolean;
    38→  lastMessageAgeMs: number;
    39→  bridgeConnected: boolean;
    40→
    41→  // Computed status for TopBar StatusDot
    42→  dotStatus: DotStatus;
    43→
    44→  // True while WS is not yet connected OR bridge is still launching.
    45→  // Clears once the WS has connected and the bridge reaches a stable state.
    46→  isStartingUp: boolean;
    47→
    48→  // Derived: true for 15s after status transitions to "running" from non-running,
    49→  // cleared when devices become non-empty or the timeout expires.
    50→  isRecovering: boolean;
    51→
    52→  // Derived: client-side countdown from nextRetryInS, decrements every 1s.
    53→  // null when no countdown is active.
    54→  countdownSecondsRemaining: number | null;
    55→
    56→  // Actions
    57→  setWsConnected: (connected: boolean) => void;
    58→  setBridgeState: (state: BridgeState) => void;
    59→  setPioneerStatus: (isReceiving: boolean, ageMs: number, bridgeConnected: boolean) => void;
    60→}
    61→
    62→function computeDotStatus(status: BridgeStatus): DotStatus {
    63→  if (status === "running") return "connected";
    64→  if (status === "fallback" || status === "waiting_for_hardware") return "degraded";
    65→  return "disconnected";
    66→}
    67→
    68→/** Startup is in progress until WS is open AND bridge has left "starting". */
    69→function computeIsStartingUp(wsConnected: boolean, status: BridgeStatus): boolean {
    70→  return !wsConnected || status === "starting";
    71→}
    72→
    73→// --- Timer management for isRecovering and countdownSecondsRemaining ---
    74→
    75→let recoveryTimer: ReturnType<typeof setTimeout> | null = null;
    76→let countdownInterval: ReturnType<typeof setInterval> | null = null;
    77→
    78→function clearRecoveryTimer(): void {
    79→  if (recoveryTimer !== null) {
    80→    clearTimeout(recoveryTimer);
    81→    recoveryTimer = null;
    82→  }
    83→}
    84→
    85→function clearCountdownInterval(): void {
    86→  if (countdownInterval !== null) {
    87→    clearInterval(countdownInterval);
    88→    countdownInterval = null;
    89→  }
    90→}
    91→
    92→function startRecoveryTimer(): void {
    93→  clearRecoveryTimer();
    94→  recoveryTimer = setTimeout(() => {
    95→    recoveryTimer = null;
    96→    useBridgeStore.setState({ isRecovering: false });
    97→  }, 15_000);
    98→}
    99→
   100→function startCountdown(initialSeconds: number): void {
   101→  clearCountdownInterval();
   102→  useBridgeStore.setState({ countdownSecondsRemaining: initialSeconds });
   103→  countdownInterval = setInterval(() => {
   104→    const current = useBridgeStore.getState().countdownSecondsRemaining;
   105→    if (current === null || current <= 1) {
   106→      clearCountdownInterval();
   107→      useBridgeStore.setState({ countdownSecondsRemaining: 0 });
   108→    } else {
   109→      useBridgeStore.setState({ countdownSecondsRemaining: current - 1 });
   110→    }
   111→  }, 1_000);
   112→}
   113→
   114→export const useBridgeStore = create<BridgeStoreState>((set) => ({
   115→  wsConnected: false,
   116→  status: "stopped",
   117→  port: 0,
   118→  networkInterface: null,
   119→  jarExists: false,
   120→  jreAvailable: false,
   121→  restartCount: 0,
   122→  restartAttempt: 0,
   123→  nextRetryInS: null,
   124→  routeCorrect: null,
   125→  routeWarning: null,
   126→  devices: {},
   127→  players: {},
   128→  isReceiving: false,
